// Cumsum op_host — tiling calculation + EXEC_KERNEL_CMD launch
// Format: Abs-style with platform_ascendc and EXEC_KERNEL_CMD

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_cumsum.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_ROWS = 64;
constexpr int32_t DEFAULT_TILE_LEN = 256;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor cumsum(const at::Tensor &x, int64_t dim)
{
    TORCH_CHECK(x.dim() >= 1, "x must be at least 1-D");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
            x.scalar_type() == at::kBFloat16,
        "x must be float16, float32, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int64_t rank = x.dim();
    if (dim < 0) {
        dim = rank + dim;
    }
    TORCH_CHECK(dim >= 0 && dim < rank, "dim out of range");

    // Permute scan axis to last dimension
    std::vector<int64_t> perm;
    for (int64_t i = 0; i < rank; ++i) {
        if (i != dim) {
            perm.push_back(i);
        }
    }
    perm.push_back(dim);

    at::Tensor x_perm = x.permute(perm).contiguous();

    // Flatten leading dims into numRows
    int64_t numRows = 1;
    for (int64_t i = 0; i < rank - 1; ++i) {
        numRows *= x_perm.sizes()[i];
    }
    int64_t rowLen = x_perm.sizes()[rank - 1];

    // Flatten to 2D for kernel
    at::Tensor x_2d = x_perm.reshape({numRows, rowLen});
    at::Tensor y_2d = at::empty_like(x_2d);

    // Tiling
    int32_t rowNum = static_cast<int32_t>((numRows + DEFAULT_BLOCK_ROWS - 1) / DEFAULT_BLOCK_ROWS);
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, rowNum));
    int32_t tasksPerCore = (rowNum + usedCoreNum - 1) / usedCoreNum;

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Mixed accumulation precision strategy
    // For fp16: small tensors (rowLen <= 512) use fp16 accumulation to match PyTorch
    // For fp16: large tensors use fp32 accumulation
    int64_t useFp32Acc = 1;
    if (dtypeFlag == 1 && rowLen <= 512) {
        useFp32Acc = 0;  // fp16 accumulation for small tensors
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int64_t tileLen = DEFAULT_TILE_LEN;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    int64_t numRowsL = numRows;
    int64_t rowLenL = rowLen;
    int64_t tileLenL = tileLen;
    int64_t useFp32AccL = useFp32Acc;
    int64_t dtypeFlagL = dtypeFlag;

    EXEC_KERNEL_CMD(cumsum, blockDim,
                    x_2d, y_2d,
                    numRowsL, rowLenL, tileLenL,
                    useFp32AccL, dtypeFlagL);

    // Reshape back to permuted shape
    std::vector<int64_t> permShape;
    for (int64_t i = 0; i < rank - 1; ++i) {
        permShape.push_back(x_perm.sizes()[i]);
    }
    permShape.push_back(rowLen);
    at::Tensor y_perm = y_2d.reshape(permShape);

    // Inverse permute to restore original axis order
    std::vector<int64_t> invPerm(rank);
    for (int64_t i = 0; i < rank; ++i) {
        invPerm[perm[i]] = i;
    }
    at::Tensor y = y_perm.permute(invPerm).contiguous();

    return y;
}

}  // namespace ascend_kernel
