13	 * \brief TBuf临时缓冲区样例，展示TBuf在数据类型转换中的应用
14	 */
15	
16	#include <cassert>
17	#include "acl/acl.h"
18	#include "kernel_operator.h"
19	#include "data_utils.h"
20	
21	#ifdef ASCENDC_CPU_DEBUG
22	#include "cpu_debug_launch.h"
23	#endif
24	
25	template <uint32_t totalLength>
26	__global__ __vector__ void tmp_buffer_custom(__gm__ uint8_t* x, __gm__ uint8_t* y, __gm__ uint8_t* z)
27	{
28	    AscendC::TPipe pipe;
29	
30	    AscendC::GlobalTensor<bfloat16_t> xGm;
31	    AscendC::GlobalTensor<bfloat16_t> yGm;
32	    AscendC::GlobalTensor<bfloat16_t> zGm;
33	    xGm.SetGlobalBuffer((__gm__ bfloat16_t*)x, totalLength);
34	    yGm.SetGlobalBuffer((__gm__ bfloat16_t*)y, totalLength);
35	    zGm.SetGlobalBuffer((__gm__ bfloat16_t*)z, totalLength);
36	
37	    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueueX;
38	    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueueY;
39	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueueZ;
40	    pipe.InitBuffer(inQueueX, 1, totalLength * sizeof(bfloat16_t));
41	    pipe.InitBuffer(inQueueY, 1, totalLength * sizeof(bfloat16_t));
42	    pipe.InitBuffer(outQueueZ, 1, totalLength * sizeof(bfloat16_t));
43	
44	    // 初始化TBuf临时缓冲区，用于存储类型转换后的float数据
45	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf0;
46	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
47	    pipe.InitBuffer(tmpBuf0, totalLength * sizeof(float));
48	    pipe.InitBuffer(tmpBuf1, totalLength * sizeof(float));
49	
50	    AscendC::LocalTensor<bfloat16_t> xLocal = inQueueX.AllocTensor<bfloat16_t>();
51	    AscendC::LocalTensor<bfloat16_t> yLocal = inQueueY.AllocTensor<bfloat16_t>();
52	    AscendC::DataCopy(xLocal, xGm, totalLength);
53	    AscendC::DataCopy(yLocal, yGm, totalLength);
54	    inQueueX.EnQue(xLocal);
55	    inQueueY.EnQue(yLocal);
56	
57	    xLocal = inQueueX.DeQue<bfloat16_t>();
58	    yLocal = inQueueY.DeQue<bfloat16_t>();
59	    AscendC::LocalTensor<bfloat16_t> zLocal = outQueueZ.AllocTensor<bfloat16_t>();
60	    AscendC::LocalTensor<float> tmpTensor0 = tmpBuf0.Get<float>();
61	    AscendC::LocalTensor<float> tmpTensor1 = tmpBuf1.Get<float>();
62	    // 使用Cast接口将bfloat16_t转换为float类型，存入TBuf临时缓冲区
63	    AscendC::Cast(tmpTensor0, xLocal, AscendC::RoundMode::CAST_NONE, totalLength);
64	    AscendC::Cast(tmpTensor1, yLocal, AscendC::RoundMode::CAST_NONE, totalLength);
65	    AscendC::Add(tmpTensor0, tmpTensor0, tmpTensor1, totalLength);
66	    AscendC::Cast(zLocal, tmpTensor0, AscendC::RoundMode::CAST_RINT, totalLength);
67	    outQueueZ.EnQue<bfloat16_t>(zLocal);
68	    inQueueX.FreeTensor(xLocal);
69	    inQueueY.FreeTensor(yLocal);
70	
71	    zLocal = outQueueZ.DeQue<bfloat16_t>();
72	    AscendC::DataCopy(zGm, zLocal, totalLength);
73	    outQueueZ.FreeTensor(zLocal);
74	}
75	
76	int32_t main(int32_t argc, char* argv[])
77	{
78	    uint32_t numBlocks = 1;
79	    constexpr uint32_t totalLength = 2048;
80	    size_t inputByteSize = totalLength * sizeof(uint16_t);
81	    size_t outputByteSize = totalLength * sizeof(uint16_t);
82	
83	    int32_t deviceId = 0;
84	    aclrtStream stream = nullptr;
85	
86	    uint8_t* xHost = nullptr;
87	    uint8_t* yHost = nullptr;
88	    uint8_t* zHost = nullptr;
89	    uint8_t* xDevice = nullptr;
90	    uint8_t* yDevice = nullptr;
91	    uint8_t* zDevice = nullptr;
92	
93	    // ACL initialization related operations
94	    aclError ret = ACL_SUCCESS;
95	    ret = aclInit(nullptr);
96	    assert(ret == ACL_SUCCESS && "aclInit failed!");
97	
98	    ret = aclrtSetDevice(deviceId);
99	    assert(ret == ACL_SUCCESS && "aclrtSetDevice failed!");
100	
101	    ret = aclrtCreateStream(&stream);
102	    assert(ret == ACL_SUCCESS && "aclrtCreateStream failed!");
103	
104	    // Host memory allocation
105	    ret = aclrtMallocHost((void**)(&xHost), inputByteSize);
106	    assert(ret == ACL_SUCCESS && "aclrtMallocHost xHost failed!");
107	
108	    ret = aclrtMallocHost((void**)(&yHost), inputByteSize);
109	    assert(ret == ACL_SUCCESS && "aclrtMallocHost yHost failed!");
110	
111	    ret = aclrtMallocHost((void**)(&zHost), outputByteSize);
112	    assert(ret == ACL_SUCCESS && "aclrtMallocHost zHost failed!");
113	
114	    // Device memory allocation
115	    ret = aclrtMalloc((void**)&xDevice, inputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
116	    assert(ret == ACL_SUCCESS && "aclrtMalloc xDevice failed!");
117	
118	    ret = aclrtMalloc((void**)&yDevice, inputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
119	    assert(ret == ACL_SUCCESS && "aclrtMalloc yDevice failed!");
120	
121	    ret = aclrtMalloc((void**)&zDevice, outputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
122	    assert(ret == ACL_SUCCESS && "aclrtMalloc zDevice failed!");
123	
124	    ReadFile("./input/input_x.bin", inputByteSize, xHost, inputByteSize);
125	    ReadFile("./input/input_y.bin", inputByteSize, yHost, inputByteSize);
126	
127	    // Host to device memory copy
128	    ret = aclrtMemcpy(xDevice, inputByteSize, xHost, inputByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
129	    assert(ret == ACL_SUCCESS && "aclrtMemcpy xHost to xDevice failed!");
130	
131	    ret = aclrtMemcpy(yDevice, inputByteSize, yHost, inputByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
132	    assert(ret == ACL_SUCCESS && "aclrtMemcpy yHost to yDevice failed!");
133	
134	    // Launch custom operator
135	    tmp_buffer_custom<totalLength><<<numBlocks, nullptr, stream>>>(xDevice, yDevice, zDevice);
136	    ret = aclrtSynchronizeStream(stream);
137	    assert(ret == ACL_SUCCESS && "aclrtSynchronizeStream failed!");
138	
139	    // Device to host memory copy
140	    ret = aclrtMemcpy(zHost, outputByteSize, zDevice, outputByteSize, ACL_MEMCPY_DEVICE_TO_HOST);
141	    assert(ret == ACL_SUCCESS && "aclrtMemcpy zDevice to zHost failed!");
142	    WriteFile("./v1_baseline_runs_pass2/output.bin", zHost, outputByteSize);
143	
144	    // Resource release: Follow the order of first allocation then release to avoid memory leaks
145	    if (xDevice != nullptr) {
146	        aclrtFree(xDevice);
147	        xDevice = nullptr;
148	    }
149	    if (yDevice != nullptr) {
150	        aclrtFree(yDevice);
151	        yDevice = nullptr;
152	    }
153	    if (zDevice != nullptr) {
154	        aclrtFree(zDevice);
155	        zDevice = nullptr;
156	    }
157	    if (xHost != nullptr) {
158	        aclrtFreeHost(xHost);
159	        xHost = nullptr;
160	    }
161	    if (yHost != nullptr) {
162	        aclrtFreeHost(yHost);
163	        yHost = nullptr;
164	    }
165	    if (zHost != nullptr) {
166	        aclrtFreeHost(zHost);
167	        zHost = nullptr;
168	    }
169	
170	    if (stream != nullptr) {
171	        aclrtDestroyStream(stream);
172	        stream = nullptr;
173	    }
174	
175	    aclrtResetDevice(deviceId);
176	    aclFinalize();
177	
178	    return 0;
179	}
