11	// AscendC Cumsum kernel — prefix sum along last dimension.
12	// Supports float32, float16, bfloat16 with mixed accumulation precision.
13	// Format: Abs-style with dtype dispatch in __global__ entry.
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 2;
18	
19	// ---------------------------------------------------------------------------
20	// Inline helpers
21	// ---------------------------------------------------------------------------
22	
23	template <typename T>
24	__aicore__ inline void LoadGmToUb(
25	    AscendC::LocalTensor<T> &dst,
26	    AscendC::GlobalTensor<T> src,
27	    uint32_t count)
28	{
29	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
30	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
31	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
32	}
33	
34	template <typename T>
35	__aicore__ inline void StoreUbToGm(
36	    AscendC::GlobalTensor<T> dst,
37	    AscendC::LocalTensor<T> &src,
38	    uint32_t count)
39	{
40	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
41	    AscendC::DataCopyPad(dst, src, copyParams);
42	}
43	
44	// =========================================================================
45	// Cumsum kernel — processes prefix sum along the last dimension
46	// =========================================================================
47	
48	template <typename dataType>
49	class CumsumKernel {
50	public:
51	    __aicore__ inline void Init(
52	        GM_ADDR x, GM_ADDR y,
53	        int64_t numRows, int64_t rowLen, int64_t tileLen,
54	        int64_t useFp32Acc)
55	    {
56	        this->numRows = static_cast<int32_t>(numRows);
57	        this->rowLen = static_cast<int32_t>(rowLen);
58	        this->tileLen = static_cast<int32_t>(tileLen);
59	        this->useFp32Acc = static_cast<int32_t>(useFp32Acc);
60	
61	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(numRows) * rowLen);
62	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(numRows) * rowLen);
63	
64	        if ASCEND_IS_AIV {
65	            InitAivBuffers();
66	        }
67	    }
68	
69	    __aicore__ inline void InitAivBuffers()
70	    {
71	        subBlockRows_ = blockRows / AscendC::GetSubBlockNum();
72	        rowNum = (numRows + blockRows - 1) / blockRows;
73	        tasksPerCore = (rowNum + numPhysicalCores - 1) / numPhysicalCores;
74	        tileNum = (rowLen + tileLen - 1) / tileLen;
75	
76	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileLen * sizeof(dataType));
77	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileLen * sizeof(dataType));
78	
79	        if constexpr (!std::is_same_v<dataType, float>) {
80	            pipe.InitBuffer(xCastBuf_, tileLen * sizeof(float));
81	            pipe.InitBuffer(yCastBuf_, tileLen * sizeof(float));
82	        }
83	    }
84	
85	    __aicore__ inline void Process()
86	    {
87	        if ASCEND_IS_AIV {
88	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
89	            const int subBlockIdx = AscendC::GetSubBlockIdx();
90	
91	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
92	                const int bx = coreIdx * tasksPerCore + localIdx;
93	                if (bx >= rowNum) {
94	                    continue;
95	                }
96	
97	                for (int row = 0; row < subBlockRows_; ++row) {
98	                    const int rowIdx = bx * blockRows + subBlockIdx * subBlockRows_ + row;
99	                    if (rowIdx < numRows) {
100	                        ProcessRow(rowIdx);
101	                    }
102	                }
103	            }
104	        }
105	    }
106	
107	private:
108	    static constexpr int blockRows = 64;
109	    static constexpr int numPhysicalCores = 20;
110	
111	    __aicore__ inline void CopyIn(int32_t rowIdx, int32_t tStart, int32_t curTileLen)
112	    {
113	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
114	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * rowLen + tStart], static_cast<uint32_t>(curTileLen));
115	        xInQueue_.EnQue(xInLocal_);
116	    }
117	
118	    __aicore__ inline void CopyOut(int32_t rowIdx, int32_t tStart, int32_t curTileLen)
119	    {
120	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
121	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * rowLen + tStart], yOutLocal_, static_cast<uint32_t>(curTileLen));
122	        yOutQueue_.FreeTensor(yOutLocal_);
123	    }
124	
125	    __aicore__ inline void ProcessRow(int32_t rowIdx)
126	    {
127	        // Initialize running accumulator to 0
128	        float acc = 0.0f;
129	
130	        for (int t = 0; t < tileNum; ++t) {
131	            int tStart = t * tileLen;
132	            int tEnd = tStart + tileLen;
133	            if (tEnd > rowLen) { tEnd = rowLen; }
134	            int curTileLen = tEnd - tStart;
135	
136	            CopyIn(rowIdx, tStart, curTileLen);
137	
138	            xInLocal_ = xInQueue_.DeQue<dataType>();
139	            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
140	
141	            if constexpr (std::is_same_v<dataType, float>) {
142	                // FP32 path: direct accumulation
143	                for (int i = 0; i < curTileLen; ++i) {
144	                    acc += xInLocal_.GetValue(i);
145	                    yOutLocal_.SetValue(i, acc);
146	                }
147	            } else {
148	                // FP16/BF16 path: cast to FP32, accumulate, cast back
149	                float xFp32[256];
150	                float yFp32[256];
151	
152	                // Cast input to FP32
153	                for (int i = 0; i < curTileLen; ++i) {
154	                    xFp32[i] = static_cast<float>(xInLocal_.GetValue(i));
155	                }
156	
157	                if (useFp32Acc) {
158	                    // FP32 accumulation path (large tensors)
159	                    for (int i = 0; i < curTileLen; ++i) {
160	                        acc += xFp32[i];
161	                        yFp32[i] = acc;
162	                    }
163	                } else {
164	                    // FP16 accumulation path (small tensors, match PyTorch rounding)
165	                    for (int i = 0; i < curTileLen; ++i) {
166	                        // Cast acc to half and back to match PyTorch fp16 behavior
167	                        half accHalf = static_cast<half>(acc);
168	                        acc = static_cast<float>(accHalf);
169	                        acc += xFp32[i];
170	                        yFp32[i] = acc;
171	                    }
172	                }
173	
174	                // Cast output back to original dtype
175	                for (int i = 0; i < curTileLen; ++i) {
176	                    if constexpr (std::is_same_v<dataType, half>) {
177	                        yOutLocal_.SetValue(i, static_cast<half>(yFp32[i]));
178	                    } else {
179	                        yOutLocal_.SetValue(i, static_cast<bfloat16_t>(yFp32[i]));
180	                    }
181	                }
182	            }
183	
184	            xInQueue_.FreeTensor(xInLocal_);
185	            yOutQueue_.EnQue(yOutLocal_);
186	            CopyOut(rowIdx, tStart, curTileLen);
187	        }
188	    }
189	
190	private:
191	    int32_t numRows = 0;
192	    int32_t rowLen = 0;
193	    int32_t tileLen = 0;
194	    int32_t useFp32Acc = 1;
195	    int32_t tileNum = 0;
196	    int32_t rowNum = 0;
197	    int32_t tasksPerCore = 0;
198	    int subBlockRows_ = 0;
199	
200	    AscendC::TPipe pipe;
201	    AscendC::GlobalTensor<dataType> xGM_;
202	    AscendC::GlobalTensor<dataType> yGM_;
203	
204	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
205	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
206	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
207	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
208	
209	    AscendC::LocalTensor<dataType> xInLocal_;
210	    AscendC::LocalTensor<dataType> yOutLocal_;
211	};
212	
213	// =========================================================================
214	// Dtype dispatch helper
215	// =========================================================================
216	
217	template <template <typename> class Kernel>
218	__aicore__ inline void DispatchCumsum(
219	    GM_ADDR x, GM_ADDR y,
220	    int64_t numRows, int64_t rowLen, int64_t tileLen,
221	    int64_t useFp32Acc, int64_t dtypeFlag)
222	{
223	    if (dtypeFlag == 0) {
224	        Kernel<float> kernel;
225	        kernel.Init(x, y, numRows, rowLen, tileLen, useFp32Acc);
226	        kernel.Process();
227	    } else if (dtypeFlag == 1) {
228	        Kernel<half> kernel;
229	        kernel.Init(x, y, numRows, rowLen, tileLen, useFp32Acc);
230	        kernel.Process();
231	    } else {
232	        Kernel<bfloat16_t> kernel;
233	        kernel.Init(x, y, numRows, rowLen, tileLen, useFp32Acc);
234	        kernel.Process();
235	    }
236	}
237	
238	// =========================================================================
239	// Kernel entry point
240	// =========================================================================
241	
242	extern "C" __global__ __aicore__ void cumsum(
243	    GM_ADDR x, GM_ADDR y,
244	    int64_t numRows, int64_t rowLen, int64_t tileLen,
245	    int64_t useFp32Acc, int64_t dtypeFlag)
246	{
247	    DispatchCumsum<CumsumKernel>(x, y, numRows, rowLen, tileLen, useFp32Acc, dtypeFlag);
248	}
