        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, MAX_TILE_LEN * sizeof(float));
            pipe.InitBuffer(yCastBuf_, MAX_TILE_LEN * sizeof(float));
