private:
    static constexpr int blockRows = 64;
    static constexpr int numPhysicalCores = 20;

    __aicore__ inline void CopyIn(int32_t rowIdx, int32_t tStart, int32_t curTileLen)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * rowLen + tStart], static_cast<uint32_t>(curTileLen));
