// Format: Abs-style with dtype dispatch in __global__ entry.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t MAX_TILE_LEN = 256;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Cumsum kernel — processes prefix sum along the last dimension
// =========================================================================

template <typename dataType>
class CumsumKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int64_t numRows, int64_t rowLen, int64_t tileLen,
        int64_t useFp32Acc)
    {
        this->numRows = static_cast<int32_t>(numRows);
        this->rowLen = static_cast<int32_t>(rowLen);
        this->tileLen = static_cast<int32_t>(tileLen);
        this->useFp32Acc = static_cast<int32_t>(useFp32Acc);

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(numRows) * rowLen);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(numRows) * rowLen);

        if ASCEND_IS_AIV {
            InitAivBuffers();
        }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockRows / AscendC::GetSubBlockNum();
        rowNum = (numRows + blockRows - 1) / blockRows;
        tasksPerCore = (rowNum + numPhysicalCores - 1) / numPhysicalCores;
        tileNum = (rowLen + tileLen - 1) / tileLen;

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileLen * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileLen * sizeof(dataType));

        // Cast buffers for FP16/BF16 paths — use TQue for proper memory management
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastQueue_, BUFFER_NUM, MAX_TILE_LEN * sizeof(float));
            pipe.InitBuffer(yCastQueue_, BUFFER_NUM, MAX_TILE_LEN * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= rowNum) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockRows + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < numRows) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    static constexpr int blockRows = 64;
    static constexpr int numPhysicalCores = 20;

    __aicore__ inline void CopyIn(int32_t rowIdx, int32_t tStart, int32_t curTileLen)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * rowLen + tStart], static_cast<uint32_t>(curTileLen));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOut(int32_t rowIdx, int32_t tStart, int32_t curTileLen)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * rowLen + tStart], yOutLocal_, static_cast<uint32_t>(curTileLen));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        // Initialize running accumulator to 0
        float acc = 0.0f;

        for (int t = 0; t < tileNum; ++t) {
            int tStart = t * tileLen;
            int tEnd = tStart + tileLen;
            if (tEnd > rowLen) { tEnd = rowLen; }
            int curTileLen = tEnd - tStart;

            CopyIn(rowIdx, tStart, curTileLen);

            xInLocal_ = xInQueue_.DeQue<dataType>();
            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();

            if constexpr (std::is_same_v<dataType, float>) {
                // FP32 path: direct accumulation using GetValue/SetValue
                for (int i = 0; i < curTileLen; ++i) {
                    acc += xInLocal_.GetValue(i);
                    yOutLocal_.SetValue(i, acc);
                }
            } else {
                // FP16/BF16 path: use Cast API for vectorized conversion
                // Cast xInLocal_ (half/bf16) -> xCastQueue_ (float)
                AscendC::LocalTensor<float> xFp32 = xCastQueue_.AllocTensor<float>();
                AscendC::LocalTensor<float> yFp32 = yCastQueue_.AllocTensor<float>();

                AscendC::Cast(xFp32, xInLocal_, AscendC::RoundMode::CAST_NONE, curTileLen);
                AscendC::PipeBarrier<PIPE_V>();

                if (useFp32Acc && !std::is_same_v<dataType, bfloat16_t>) {
                    // FP32 accumulation path (large tensors) — only for FP16
                    for (int i = 0; i < curTileLen; ++i) {
                        acc += xFp32.GetValue(i);
                        yFp32.SetValue(i, acc);
                    }
                } else if (!useFp32Acc && std::is_same_v<dataType, half>) {
                    // FP16 accumulation path (small tensors, match PyTorch rounding)
                    for (int i = 0; i < curTileLen; ++i) {
                        // Cast acc to half and back to match PyTorch fp16 behavior
                        half accHalf = static_cast<half>(acc);
                        acc = static_cast<float>(accHalf);
                        acc += xFp32.GetValue(i);
                        yFp32.SetValue(i, acc);
                    }
                } else {
                    // BF16 path or FP16 large tensor path: FP32 accumulation
                    for (int i = 0; i < curTileLen; ++i) {
                        acc += xFp32.GetValue(i);
                        yFp32.SetValue(i, acc);
                    }
                }

                // Cast yFp32 (float) -> yOutLocal_ (half/bf16) using CAST_NONE
                AscendC::Cast(yOutLocal_, yFp32, AscendC::RoundMode::CAST_NONE, curTileLen);
                AscendC::PipeBarrier<PIPE_V>();

                xCastQueue_.FreeTensor(xFp32);
                yCastQueue_.FreeTensor(yFp32);
            }

            xInQueue_.FreeTensor(xInLocal_);
            yOutQueue_.EnQue(yOutLocal_);
            CopyOut(rowIdx, tStart, curTileLen);
        }
    }

private:
    int32_t numRows = 0;
    int32_t rowLen = 0;
    int32_t tileLen = 0;
    int32_t useFp32Acc = 1;
    int32_t tileNum = 0;
    int32_t rowNum = 0;
    int32_t tasksPerCore = 0;
    int subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECCALC, BUFFER_NUM> xCastQueue_;
    AscendC::TQue<AscendC::TPosition::VECCALC, BUFFER_NUM> yCastQueue_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
};

