49	template <typename dataType>
50	class CumsumKernel {
51	public:
52	    __aicore__ inline void Init(
53	        GM_ADDR x, GM_ADDR y,
54	        int64_t numRows, int64_t rowLen, int64_t tileLen,
55	        int64_t useFp32Acc)
56	    {
57	        this->numRows = static_cast<int32_t>(numRows);
58	        this->rowLen = static_cast<int32_t>(rowLen);
59	        this->tileLen = static_cast<int32_t>(tileLen);
60	        this->useFp32Acc = static_cast<int32_t>(useFp32Acc);
61	
62	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(numRows) * rowLen);
63	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(numRows) * rowLen);
64	
65	        if ASCEND_IS_AIV {
66	            InitAivBuffers();
67	        }
68	    }
69	
70	    __aicore__ inline void InitAivBuffers()
71	    {
72	        subBlockRows_ = blockRows / AscendC::GetSubBlockNum();
73	        rowNum = (numRows + blockRows - 1) / blockRows;
74	        tasksPerCore = (rowNum + numPhysicalCores - 1) / numPhysicalCores;
75	        tileNum = (rowLen + tileLen - 1) / tileLen;
76	
77	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileLen * sizeof(dataType));
78	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileLen * sizeof(dataType));
79	
80	        // Cast buffers for FP16/BF16 paths — use TQue for proper memory management
81	        if constexpr (!std::is_same_v<dataType, float>) {
82	            pipe.InitBuffer(xCastQueue_, BUFFER_NUM, MAX_TILE_LEN * sizeof(float));
83	            pipe.InitBuffer(yCastQueue_, BUFFER_NUM, MAX_TILE_LEN * sizeof(float));
84	        }
85	    }
86	
87	    __aicore__ inline void Process()
88	    {
89	        if ASCEND_IS_AIV {
90	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
91	            const int subBlockIdx = AscendC::GetSubBlockIdx();
92	
93	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
94	                const int bx = coreIdx * tasksPerCore + localIdx;
95	                if (bx >= rowNum) {
96	                    continue;
97	                }
98	
99	                for (int row = 0; row < subBlockRows_; ++row) {
100	                    const int rowIdx = bx * blockRows + subBlockIdx * subBlockRows_ + row;
101	                    if (rowIdx < numRows) {
102	                        ProcessRow(rowIdx);
103	                    }
104	                }
105	            }
106	        }
107	    }
108	
109	private:
110	    static constexpr int blockRows = 64;
111	    static constexpr int numPhysicalCores = 20;
112	
113	    __aicore__ inline void CopyIn(int32_t rowIdx, int32_t tStart, int32_t curTileLen)
114	    {
115	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
116	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * rowLen + tStart], static_cast<uint32_t>(curTileLen));
117	        xInQueue_.EnQue(xInLocal_);
118	    }
119	
120	    __aicore__ inline void CopyOut(int32_t rowIdx, int32_t tStart, int32_t curTileLen)
121	    {
122	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
123	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * rowLen + tStart], yOutLocal_, static_cast<uint32_t>(curTileLen));
124	        yOutQueue_.FreeTensor(yOutLocal_);
125	    }
126	
127	    __aicore__ inline void ProcessRow(int32_t rowIdx)
128	    {
129	        // Initialize running accumulator to 0
130	        float acc = 0.0f;
131	
132	        for (int t = 0; t < tileNum; ++t) {
133	            int tStart = t * tileLen;
134	            int tEnd = tStart + tileLen;
135	            if (tEnd > rowLen) { tEnd = rowLen; }
136	            int curTileLen = tEnd - tStart;
137	
138	            CopyIn(rowIdx, tStart, curTileLen);
139	
140	            xInLocal_ = xInQueue_.DeQue<dataType>();
141	            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
142	
143	            if constexpr (std::is_same_v<dataType, float>) {
144	                // FP32 path: direct accumulation using GetValue/SetValue
145	                for (int i = 0; i < curTileLen; ++i) {
146	                    acc += xInLocal_.GetValue(i);
147	                    yOutLocal_.SetValue(i, acc);
148	                }
149	            } else {
150	                // FP16/BF16 path: use Cast API for vectorized conversion
151	                // Cast xInLocal_ (half/bf16) -> xCastQueue_ (float)
152	                AscendC::LocalTensor<float> xFp32 = xCastQueue_.AllocTensor<float>();
153	                AscendC::LocalTensor<float> yFp32 = yCastQueue_.AllocTensor<float>();
154	
155	                AscendC::Cast(xFp32, xInLocal_, AscendC::RoundMode::CAST_NONE, curTileLen);
156	                AscendC::PipeBarrier<PIPE_V>();
157	
158	                if (useFp32Acc && !std::is_same_v<dataType, bfloat16_t>) {
159	                    // FP32 accumulation path (large tensors) — only for FP16
160	                    for (int i = 0; i < curTileLen; ++i) {
161	                        acc += xFp32.GetValue(i);
162	                        yFp32.SetValue(i, acc);
163	                    }
164	                } else if (!useFp32Acc && std::is_same_v<dataType, half>) {
165	                    // FP16 accumulation path (small tensors, match PyTorch rounding)
166	                    for (int i = 0; i < curTileLen; ++i) {
167	                        // Cast acc to half and back to match PyTorch fp16 behavior
168	                        half accHalf = static_cast<half>(acc);
169	                        acc = static_cast<float>(accHalf);
170	                        acc += xFp32.GetValue(i);
171	                        yFp32.SetValue(i, acc);
172	                    }
173	                } else {
174	                    // BF16 path or FP16 large tensor path: FP32 accumulation
175	                    for (int i = 0; i < curTileLen; ++i) {
176	                        acc += xFp32.GetValue(i);
177	                        yFp32.SetValue(i, acc);
178	                    }
179	                }
180	
181	                // Cast yFp32 (float) -> yOutLocal_ (half/bf16) using CAST_NONE
182	                AscendC::Cast(yOutLocal_, yFp32, AscendC::RoundMode::CAST_NONE, curTileLen);
183	                AscendC::PipeBarrier<PIPE_V>();
184	
185	                xCastQueue_.FreeTensor(xFp32);
186	                yCastQueue_.FreeTensor(yFp32);
187	            }
188	
189	            xInQueue_.FreeTensor(xInLocal_);
190	            yOutQueue_.EnQue(yOutLocal_);
191	            CopyOut(rowIdx, tStart, curTileLen);
192	        }
193	    }
194	
