10	
11	// Cumsum op_host — tiling calculation + EXEC_KERNEL_CMD launch
12	// Format: Abs-style with platform_ascendc and EXEC_KERNEL_CMD
13	
14	#include <algorithm>
15	#include <cstdint>
16	
17	#include <torch/extension.h>
18	#include <torch/library.h>
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	
23	#include "aclrtlaunch_cumsum.h"
24	
25	// ---------------------------------------------------------------------------
26	// Tiling constants
27	// ---------------------------------------------------------------------------
28	
29	constexpr int32_t DEFAULT_BLOCK_ROWS = 64;
30	constexpr int32_t DEFAULT_TILE_LEN = 256;
31	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
32	
33	// ---------------------------------------------------------------------------
34	// Host function
35	// ---------------------------------------------------------------------------
36	
37	namespace ascend_kernel {
38	
39	at::Tensor cumsum(const at::Tensor &x, int64_t dim)
40	{
41	    TORCH_CHECK(x.dim() >= 1, "x must be at least 1-D");
42	    TORCH_CHECK(
43	        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
44	            x.scalar_type() == at::kBFloat16,
45	        "x must be float16, float32, or bfloat16");
46	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
47	
48	    int64_t rank = x.dim();
49	    if (dim < 0) {
50	        dim = rank + dim;
51	    }
52	    TORCH_CHECK(dim >= 0 && dim < rank, "dim out of range");
53	
54	    // Permute scan axis to last dimension
55	    std::vector<int64_t> perm;
56	    for (int64_t i = 0; i < rank; ++i) {
57	        if (i != dim) {
58	            perm.push_back(i);
59	        }
60	    }
61	    perm.push_back(dim);
62	
63	    at::Tensor x_perm = x.permute(perm).contiguous();
64	
65	    // Flatten leading dims into numRows
66	    int64_t numRows = 1;
67	    for (int64_t i = 0; i < rank - 1; ++i) {
68	        numRows *= x_perm.sizes()[i];
69	    }
70	    int64_t rowLen = x_perm.sizes()[rank - 1];
71	
72	    // Flatten to 2D for kernel
73	    at::Tensor x_2d = x_perm.reshape({numRows, rowLen});
74	    at::Tensor y_2d = at::empty_like(x_2d);
75	
76	    // Tiling
77	    int32_t rowNum = static_cast<int32_t>((numRows + DEFAULT_BLOCK_ROWS - 1) / DEFAULT_BLOCK_ROWS);
78	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, rowNum));
79	    int32_t tasksPerCore = (rowNum + usedCoreNum - 1) / usedCoreNum;
80	
81	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
82	    int64_t dtypeFlag = 0;
83	    if (x.scalar_type() == at::kHalf) {
84	        dtypeFlag = 1;
85	    } else if (x.scalar_type() == at::kBFloat16) {
86	        dtypeFlag = 2;
87	    }
88	
89	    // For bfloat16, convert to float32 on host, run fp32 kernel, then convert back
90	    if (x.scalar_type() == at::kBFloat16) {
91	        at::Tensor x_fp32 = x_2d.to(at::kFloat);
92	        at::Tensor y_fp32 = at::empty_like(x_fp32);
93	
94	        int64_t bf16DtypeFlag = 0;  // fp32
95	        int64_t bf16UseFp32Acc = 1;
96	
97	        EXEC_KERNEL_CMD(cumsum, blockDim,
98	                        x_fp32, y_fp32,
99	                        numRowsL, rowLenL, tileLenL,
100	                        bf16UseFp32Acc, bf16DtypeFlag);
101	
102	        y_2d = y_fp32.to(at::kBFloat16);
103	    } else {
104	        // Mixed accumulation precision strategy for FP16
105	        // For fp16: always use fp16 accumulation to match np.cumsum(..., dtype=np.float16)
106	        int64_t useFp32Acc = 1;
107	        if (dtypeFlag == 1) {
108	            useFp32Acc = 0;  // fp16 accumulation for all fp16 tensors
109	        }
110	
111	        int64_t useFp32AccL = useFp32Acc;
112	        int64_t dtypeFlagL = dtypeFlag;
113	
114	        EXEC_KERNEL_CMD(cumsum, blockDim,
115	                        x_2d, y_2d,
116	                        numRowsL, rowLenL, tileLenL,
117	                        useFp32AccL, dtypeFlagL);
118	    }
119	
120	    // Reshape back to permuted shape
121	    std::vector<int64_t> permShape;
122	    for (int64_t i = 0; i < rank - 1; ++i) {
123	        permShape.push_back(x_perm.sizes()[i]);
124	    }
125	    permShape.push_back(rowLen);
126	    at::Tensor y_perm = y_2d.reshape(permShape);
127	
128	    // Inverse permute to restore original axis order
129	    std::vector<int64_t> invPerm(rank);
130	    for (int64_t i = 0; i < rank; ++i) {
131	        invPerm[perm[i]] = i;
132	    }
133	    at::Tensor y = y_perm.permute(invPerm).contiguous();
134	
135	    return y;
136	}
137	
138	}  // namespace ascend_kernel
